import pyomo.environ as pyo

DATA = {
    "A": [0, 1, 2],
    "E": {0: 201, 1: 234, 2: 29},
    "L": {0: 261, 1: 294, 2: 89},
    "early_cost": {0: 37, 1: 99, 2: 90},
    "late_cost": {0: 73, 1: 84, 2: 56},
    "sep": {
        (0, 1): 11, (1, 0): 27,
        (0, 2): 9,  (2, 0): 232,
        (1, 2): 9,  (2, 1): 265,
    },
    "bigM": 1000,
}

def build_model(data=None):
    d = data or DATA
    I = d["A"]
    E = d["E"]; L = d["L"]
    sep = d["sep"]
    early = d["early_cost"]; late = d["late_cost"]
    M = max(sep.values()) + max(abs(L[i] - L[j]) for i in I for j in I if i != j) + max(L.values())

    model = pyo.ConcreteModel()
    model.I = pyo.Set(initialize=I)
    model.ordered = pyo.Set(initialize=[(i, j) for i in I for j in I if i != j], dimen=2)
    model.pairs = pyo.Set(initialize=[(min(i, j), max(i, j)) for i in I for j in I if i < j], dimen=2)

    def t_bounds(m, i):
        return (E[i], L[i])

    model.t = pyo.Var(model.I, bounds=t_bounds, within=pyo.NonNegativeReals)
    model.e = pyo.Var(model.I, within=pyo.NonNegativeReals)
    model.l = pyo.Var(model.I, within=pyo.NonNegativeReals)
    model.z = pyo.Var(model.pairs, within=pyo.Binary)

    def rule_e(m, i):
        return m.e[i] >= d["E"][i] - m.t[i]

    def rule_l(m, i):
        return m.l[i] >= m.t[i] - d["L"][i]

    model.early_con = pyo.Constraint(model.I, rule=rule_e)
    model.late_con = pyo.Constraint(model.I, rule=rule_l)

    def rule_sep(m, i, j):
        if i < j:
            return m.t[j] >= m.t[i] + sep[(i, j)] - M * (1 - m.z[(i, j)])
        else:
            return m.t[j] >= m.t[i] + sep[(i, j)] - M * m.z[(j, i)]

    model.sep_con = pyo.Constraint(model.ordered, rule=rule_sep)

    def obj_rule(m):
        return sum(early[i] * m.e[i] + late[i] * m.l[i] for i in I)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)
    return model

